@using sv_3a28b01d574e4caf987e0c674fde736a.Services

<nav class="settings-sidebar">
    <h2 class="sidebar-title">Settings</h2>
    <ul class="sidebar-nav">
        @foreach (var section in _sections)
        {
            <li class="sidebar-item @(ActiveSection == section.Key ? "active" : "")"
                @onclick="() => OnSectionChanged.InvokeAsync(section.Key)">
                <span class="sidebar-icon">@section.Icon</span>
                <span class="sidebar-label">@section.Label</span>
            </li>
        }
    </ul>
</nav>

@code {
    [Parameter] public string ActiveSection { get; set; } = "Profile";
    [Parameter] public EventCallback<string> OnSectionChanged { get; set; }

    private readonly record struct SectionInfo(string Key, string Label, string Icon);

    private static readonly SectionInfo[] _sections =
    [
        new("Profile", "Profile", "👤"),
        new("Notifications", "Notifications", "🔔"),
        new("Security", "Security", "🔒"),
        new("Appearance", "Appearance", "🎨"),
    ];
}

.settings-sidebar {
    width: 240px;
    min-width: 240px;
    background: var(--sidebar-bg, #f8f9fa);
    border-right: 1px solid var(--border-color, #dee2e6);
    padding: 1.5rem 0;
    display: flex;
    flex-direction: column;
}

.sidebar-title {
    font-size: 1.25rem;
    font-weight: 600;
    padding: 0 1.5rem;
    margin: 0 0 1rem;
    color: var(--text-primary, #212529);
}

.sidebar-nav {
    list-style: none;
    padding: 0;
    margin: 0;
}

.sidebar-item {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 0.75rem 1.5rem;
    cursor: pointer;
    color: var(--text-secondary, #6c757d);
    transition: all 0.15s ease;
    border-left: 3px solid transparent;
}

.sidebar-item:hover {
    background: var(--hover-bg, #e9ecef);
    color: var(--text-primary, #212529);
}

.sidebar-item.active {
    background: var(--active-bg, #e7f1ff);
    color: var(--active-color, #0d6efd);
    border-left-color: var(--active-color, #0d6efd);
    font-weight: 600;
}

.sidebar-icon {
    font-size: 1.1rem;
    width: 1.5rem;
    text-align: center;
}

.sidebar-label {
    font-size: 0.95rem;
}

.change-password-panel {
    border: 1px solid var(--border-color, #dee2e6);
    border-radius: 8px;
    overflow: hidden;
}

.panel-toggle {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    width: 100%;
    padding: 0.875rem 1rem;
    border: none;
    background: var(--card-bg, #fff);
    font-size: 0.95rem;
    font-weight: 600;
    cursor: pointer;
    color: var(--text-primary, #212529);
    text-align: left;
}

.panel-toggle:hover {
    background: var(--hover-bg, #f8f9fa);
}

.toggle-icon {
    font-size: 0.8rem;
    width: 1rem;
}

.panel-content {
    padding: 1rem;
    border-top: 1px solid var(--border-color, #dee2e6);
    display: flex;
    flex-direction: column;
    gap: 1rem;
}

@using sv_3a28b01d574e4caf987e0c674fde736a.Services

<div class="sessions-section">
    <h4>Active Sessions</h4>
    <table class="sessions-table">
        <thead>
            <tr>
                <th>Device</th>
                <th>Location</th>
                <th>Last Active</th>
                <th></th>
            </tr>
        </thead>
        <tbody>
            @foreach (var session in Sessions)
            {
                <tr>
                    <td>@session.Device</td>
                    <td>@session.Location</td>
                    <td>@FormatLastActive(session.LastActive)</td>
                    <td>
                        @if (session.Id != CurrentSessionId)
                        {
                            <button class="btn btn-danger btn-sm"
                                    @onclick="() => RequestRevoke(session)">
                                Revoke
                            </button>
                        }
                        else
                        {
                            <span class="current-badge">Current</span>
                        }
                    </td>
                </tr>
            }
        </tbody>
    </table>
</div>

@if (_sessionToRevoke is not null)
{
    <RevokeSessionDialog Session="_sessionToRevoke"
                         OnConfirm="ConfirmRevoke"
                         OnCancel="CancelRevoke" />
}

@code {
    [Parameter, EditorRequired] public List<ActiveSession> Sessions { get; set; } = [];
    [Parameter] public string CurrentSessionId { get; set; } = "sess-1";
    [Parameter] public EventCallback<string> OnSessionRevoked { get; set; }

    private ActiveSession? _sessionToRevoke;

    private void RequestRevoke(ActiveSession session)
    {
        _sessionToRevoke = session;
    }

    private async Task ConfirmRevoke()
    {
        if (_sessionToRevoke is not null)
        {
            await OnSessionRevoked.InvokeAsync(_sessionToRevoke.Id);
            _sessionToRevoke = null;
        }
    }

    private void CancelRevoke()
    {
        _sessionToRevoke = null;
    }

    private static string FormatLastActive(DateTime lastActive)
    {
        var diff = DateTime.UtcNow - lastActive;
        if (diff.TotalMinutes < 1) return "Just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes}m ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        return $"{(int)diff.TotalDays}d ago";
    }
}

.sessions-section h4 {
    font-size: 1rem;
    font-weight: 600;
    margin: 0 0 0.75rem;
}

.sessions-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 0.9rem;
}

.sessions-table th,
.sessions-table td {
    padding: 0.75rem;
    text-align: left;
    border-bottom: 1px solid var(--border-color, #dee2e6);
}

.sessions-table th {
    font-weight: 600;
    color: var(--text-secondary, #6c757d);
    font-size: 0.8rem;
    text-transform: uppercase;
    letter-spacing: 0.05em;
}

.current-badge {
    font-size: 0.8rem;
    color: var(--success-color, #198754);
    font-weight: 600;
}

@using sv_3a28b01d574e4caf987e0c674fde736a.Services

<div class="dialog-overlay" @onclick="OnCancel">
