@using sv_3a28b01d574e4caf987e0c674fde736a.Services
@inject ISettingsService SettingsService

<div class="section">
    <h2>Profile</h2>

    @if (_loading)
    {
        <p class="loading">Loading profile…</p>
    }
    else if (_profile is not null)
    {
        <div class="profile-layout">
            <div class="avatar-area">
                <div class="avatar-preview">
                    <img src="@_avatarUrl" alt="Avatar" />
                </div>
                <div class="form-group">
                    <label>Avatar URL</label>
                    <input type="text" @bind="_avatarUrl" class="form-input" />
                </div>
            </div>

            <div class="profile-fields">
                <div class="form-group">
                    <label>Display Name</label>
                    <input type="text" @bind="_displayName" class="form-input" />
                </div>
                <div class="form-group">
                    <label>Email</label>
                    <input type="email" @bind="_email" class="form-input" />
                </div>
                <div class="form-group">
                    <label>Bio</label>
                    <textarea @bind="_bio" class="form-input" rows="4"></textarea>
                </div>
            </div>
        </div>

        @if (!string.IsNullOrEmpty(_message))
        {
            <div class="message @(_isError ? "error" : "success")">@_message</div>
        }

        <div class="actions">
            <button class="btn btn-primary" @onclick="SaveChanges" disabled="@_saving">
                @(_saving ? "Saving…" : "Save Changes")
            </button>
            <button class="btn btn-secondary" @onclick="DiscardChanges">
                Discard Changes
            </button>
        </div>
    }
</div>

@code {
    private UserProfile? _profile;
    private string _displayName = "";
    private string _email = "";
    private string _avatarUrl = "";
    private string _bio = "";
    private bool _loading = true;
    private bool _saving;
    private string? _message;
    private bool _isError;

    protected override async Task OnInitializedAsync()
    {
        await LoadProfile();
    }

    private async Task LoadProfile()
    {
        _loading = true;
        _profile = await SettingsService.GetProfileAsync();
        PopulateFields(_profile);
        _loading = false;
    }

    private void PopulateFields(UserProfile profile)
    {
        _displayName = profile.DisplayName;
        _email = profile.Email;
        _avatarUrl = profile.AvatarUrl;
        _bio = profile.Bio;
    }

    private async Task SaveChanges()
    {
        _message = null;
        _saving = true;
        try
        {
            _profile = new UserProfile(_displayName, _email, _avatarUrl, _bio);
            await SettingsService.SaveProfileAsync(_profile);
            _message = "Profile saved successfully!";
            _isError = false;
        }
        catch (Exception ex)
        {
            _message = $"Failed to save: {ex.Message}";
            _isError = true;
        }
        finally
        {
            _saving = false;
        }
    }

    private void DiscardChanges()
    {
        if (_profile is not null)
        {
            PopulateFields(_profile);
            _message = null;
        }
    }
}

