toolArgs.file_text:
@using sv_3a28b01d574e4caf987e0c674fde736a.Services
@inject ISettingsService SettingsService

<div class="section">
    <h2>Notifications</h2>

    @if (_loading)
    {
        <p class="loading">Loading notification preferences…</p>
    }
    else if (_prefs is not null)
    {
        <div class="toggle-group">
            <label class="toggle-row">
                <span class="toggle-label">
                    <strong>Email Notifications</strong>
                    <span class="toggle-description">Receive notifications via email</span>
                </span>
                <span class="toggle-switch @(_emailNotifications ? "on" : "")"
                      @onclick="() => _emailNotifications = !_emailNotifications">
                    <span class="toggle-knob"></span>
                </span>
            </label>

            <label class="toggle-row">
                <span class="toggle-label">
                    <strong>Push Notifications</strong>
                    <span class="toggle-description">Receive push notifications in browser</span>
                </span>
                <span class="toggle-switch @(_pushNotifications ? "on" : "")"
                      @onclick="() => _pushNotifications = !_pushNotifications">
                    <span class="toggle-knob"></span>
                </span>
            </label>

            <label class="toggle-row">
                <span class="toggle-label">
                    <strong>Weekly Digest</strong>
                    <span class="toggle-description">Get a weekly summary of activity</span>
                </span>
                <span class="toggle-switch @(_weeklyDigest ? "on" : "")"
                      @onclick="() => _weeklyDigest = !_weeklyDigest">
                    <span class="toggle-knob"></span>
                </span>
            </label>
        </div>

        <div class="channels-section">
            <h4>Muted Channels</h4>
            <p class="channels-hint">Checked channels will be muted.</p>
            <div class="channels-list">
                @foreach (var channel in _allChannels)
                {
                    var isMuted = _mutedChannels.Contains(channel);
                    <label class="channel-item">
                        <input type="checkbox" checked="@isMuted"
                               @onchange="e => ToggleChannel(channel, (bool)e.Value!)" />
                        <span>@channel</span>
                    </label>
                }
            </div>
        </div>

        @if (!string.IsNullOrEmpty(_message))
        {
            <div class="message success">@_message</div>
        }

        <div class="actions">
            <button class="btn btn-primary" @onclick="SavePreferences" disabled="@_saving">
                @(_saving ? "Saving…" : "Save Preferences")
            </button>
        </div>
    }
</div>

@code {
    private NotificationPrefs? _prefs;
    private bool _emailNotifications;
    private bool _pushNotifications;
    private bool _weeklyDigest;
    private List<string> _mutedChannels = [];
    private bool _loading = true;
    private bool _saving;
    private string? _message;

    private static readonly string[] _allChannels =
        ["announcements", "marketing", "social", "updates", "general", "support"];

    protected override async Task OnInitializedAsync()
    {
        _loading = true;
        _prefs = await SettingsService.GetNotificationPrefsAsync();
        _emailNotifications = _prefs.EmailNotifications;
        _pushNotifications = _prefs.PushNotifications;
        _weeklyDigest = _prefs.WeeklyDigest;
        _mutedChannels = [.. _prefs.MutedChannels];
        _loading = false;
    }

    private void ToggleChannel(string channel, bool muted)
    {
        if (muted && !_mutedChannels.Contains(channel))
            _mutedChannels.Add(channel);
        else if (!muted)
            _mutedChannels.Remove(channel);
    }

    private async Task SavePreferences()
    {
        _message = null;
        _saving = true;
        try
        {
            _prefs = new NotificationPrefs(_emailNotifications, _pushNotifications, _weeklyDigest, [.. _mutedChannels]);
            await SettingsService.SaveNotificationPrefsAsync(_prefs);
            _message = "Notification preferences saved!";
        }
        finally
        {
            _saving = false;
        }
    }
}

