toolArgs.file_text:
@using sv_3a28b01d574e4caf987e0c674fde736a.Services
@inject ISettingsService SettingsService

<div class="section">
    <h2>Security</h2>

    @if (_loading)
    {
        <p class="loading">Loading security settings…</p>
    }
    else if (_security is not null)
    {
        <ChangePasswordPanel OnPasswordChanged="ReloadSettings" />

        <div class="tfa-section">
            <div class="tfa-row">
                <span class="tfa-label">
                    <strong>Two-Factor Authentication</strong>
                    <span class="tfa-status @(_security.TwoFactorEnabled ? "enabled" : "disabled")">
                        @(_security.TwoFactorEnabled ? "● Enabled" : "○ Disabled")
                    </span>
                </span>
                <span class="toggle-switch @(_security.TwoFactorEnabled ? "on" : "")"
                      @onclick="Toggle2FA">
                    <span class="toggle-knob"></span>
                </span>
            </div>

            @if (_security.LastPasswordChange.HasValue)
            {
                <p class="last-changed">
                    Last password change: @_security.LastPasswordChange.Value.ToString("MMMM d, yyyy")
                </p>
            }
        </div>

        @if (!string.IsNullOrEmpty(_message))
        {
            <div class="message success">@_message</div>
        }

        <ActiveSessionsTable Sessions="_security.Sessions.ToList()"
                             OnSessionRevoked="RevokeSession" />
    }
</div>

@code {
    private SecuritySettings? _security;
    private bool _loading = true;
    private string? _message;

    protected override async Task OnInitializedAsync()
    {
        await LoadSettings();
    }

    private async Task LoadSettings()
    {
        _loading = true;
        _security = await SettingsService.GetSecuritySettingsAsync();
        _loading = false;
    }

    private async Task ReloadSettings()
    {
        _security = await SettingsService.GetSecuritySettingsAsync();
        _message = null;
    }

    private void Toggle2FA()
    {
        if (_security is not null)
        {
            _security = _security with { TwoFactorEnabled = !_security.TwoFactorEnabled };
        }
    }

    private async Task RevokeSession(string sessionId)
    {
        await SettingsService.RevokeSessionAsync(sessionId);
        _security = await SettingsService.GetSecuritySettingsAsync();
        _message = "Session revoked successfully.";
    }
}

