toolArgs.file_text:
@using sv_3a28b01d574e4caf987e0c674fde736a.Services
@inject ISettingsService SettingsService

<div class="section">
    <h2>Appearance</h2>

    @if (_loading)
    {
        <p class="loading">Loading appearance settings…</p>
    }
    else
    {
        <div class="setting-group">
            <h4>Theme</h4>
            <div class="radio-group">
                @foreach (var theme in _themes)
                {
                    <label class="radio-option @(_theme == theme ? "selected" : "")">
                        <input type="radio" name="theme" value="@theme"
                               checked="@(_theme == theme)"
                               @onchange="() => _theme = theme" />
                        <span>@theme</span>
                    </label>
                }
            </div>
        </div>

        <div class="setting-group">
            <h4>Font Size</h4>
            <div class="radio-group">
                @foreach (var size in _fontSizes)
                {
                    <label class="radio-option @(_fontSize == size ? "selected" : "")">
                        <input type="radio" name="fontSize" value="@size"
                               checked="@(_fontSize == size)"
                               @onchange="() => _fontSize = size" />
                        <span>@size</span>
                    </label>
                }
            </div>
        </div>

        <div class="setting-group">
            <h4>Language</h4>
            <select class="form-input" @bind="_language">
                @foreach (var lang in _languages)
                {
                    <option value="@lang">@lang</option>
                }
            </select>
        </div>

        <div class="setting-group">
            <label class="toggle-row">
                <span class="toggle-label">
                    <strong>Compact Mode</strong>
                    <span class="toggle-description">Reduce spacing and padding throughout the UI</span>
                </span>
                <span class="toggle-switch @(_compactMode ? "on" : "")"
                      @onclick="() => _compactMode = !_compactMode">
                    <span class="toggle-knob"></span>
                </span>
            </label>
        </div>

        <div class="preview-area">
            <h4>Preview</h4>
            <div class="preview-box @GetPreviewClasses()">
                <div class="preview-header">Sample Header</div>
                <p class="preview-text">
                    This is how your content will look with the selected settings.
                    The theme, font size, and compact mode are reflected here.
                </p>
                <div class="preview-actions">
                    <span class="preview-btn primary">Primary</span>
                    <span class="preview-btn secondary">Secondary</span>
                </div>
            </div>
        </div>

        @if (!string.IsNullOrEmpty(_message))
        {
            <div class="message success">@_message</div>
        }

        <div class="actions">
            <button class="btn btn-primary" @onclick="SaveAppearance" disabled="@_saving">
                @(_saving ? "Saving…" : "Save")
            </button>
        </div>
    }
</div>

@code {
    private string _theme = "Light";
    private string _fontSize = "Medium";
    private string _language = "English";
    private bool _compactMode;
    private bool _loading = true;
    private bool _saving;
    private string? _message;

    private static readonly string[] _themes = ["Light", "Dark", "System"];
    private static readonly string[] _fontSizes = ["Small", "Medium", "Large"];
    private static readonly string[] _languages =
        ["English", "Spanish", "French", "German", "Japanese", "Chinese", "Portuguese"];

    protected override async Task OnInitializedAsync()
    {
        _loading = true;
        var settings = await SettingsService.GetAppearanceAsync();
        _theme = settings.Theme;
        _fontSize = settings.FontSize;
        _language = settings.Language;
        _compactMode = settings.CompactMode;
        _loading = false;
    }

    private string GetPreviewClasses()
    {
        var classes = $"theme-{_theme.ToLowerInvariant()} font-{_fontSize.ToLowerInvariant()}";
        if (_compactMode) classes += " compact";
        return classes;
    }

    private async Task SaveAppearance()
    {
        _message = null;
        _saving = true;
        try
        {
            await SettingsService.SaveAppearanceAsync(
                new AppearanceSettings(_theme, _fontSize, _language, _compactMode));
            _message = "Appearance settings saved!";
        }
        finally
        {
            _saving = false;
        }
    }
}

