arguments.file_text:
@page "/settings"
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-dashboard">
    <SettingsSidebar ActiveSection="@_activeSection"
                     OnSectionChanged="section => _activeSection = section" />

    <main class="settings-content">
        @switch (_activeSection)
        {
            case "Profile":
                <ProfileSection />
                break;
            case "Notifications":
                <NotificationsSection />
                break;
            case "Security":
                <SecuritySection />
                break;
            case "Appearance":
                <AppearanceSection />
                break;
        }
    </main>
</div>

@code {
    private string _activeSection = "Profile";
}

.settings-dashboard {
    display: flex;
    min-height: calc(100vh - 3.5rem);
    background: var(--page-bg, #fff);
}

.settings-content {
    flex: 1;
    padding: 2rem;
    max-width: 800px;
    overflow-y: auto;
}

/* Shared styles used across sections */

:deep(.section h2) {
    font-size: 1.5rem;
    font-weight: 700;
    margin: 0 0 1.5rem;
    color: var(--text-primary, #212529);
}

:deep(.form-group) {
    display: flex;
    flex-direction: column;
    gap: 0.375rem;
}

:deep(.form-group label) {
    font-size: 0.85rem;
    font-weight: 600;
    color: var(--text-secondary, #6c757d);
    text-transform: uppercase;
    letter-spacing: 0.03em;
}

:deep(.form-input) {
    padding: 0.625rem 0.75rem;
    border: 1px solid var(--border-color, #dee2e6);
    border-radius: 6px;
    font-size: 0.95rem;
    color: var(--text-primary, #212529);
    background: var(--input-bg, #fff);
    transition: border-color 0.15s;
    width: 100%;
    box-sizing: border-box;
}

:deep(.form-input:focus) {
    outline: none;
    border-color: var(--active-color, #0d6efd);
    box-shadow: 0 0 0 3px rgba(13, 110, 253, 0.15);
}

:deep(textarea.form-input) {
    resize: vertical;
    font-family: inherit;
}

:deep(.actions) {
    display: flex;
    gap: 0.75rem;
    margin-top: 0.5rem;
}

:deep(.btn) {
    padding: 0.625rem 1.25rem;
    border: none;
    border-radius: 6px;
    font-size: 0.9rem;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.15s;
}

:deep(.btn:disabled) {
    opacity: 0.6;
    cursor: not-allowed;
}

:deep(.btn-primary) {
    background: var(--active-color, #0d6efd);
    color: white;
}

:deep(.btn-primary:hover:not(:disabled)) {
    background: #0b5ed7;
}

:deep(.btn-secondary) {
    background: var(--secondary-bg, #e9ecef);
    color: var(--text-primary, #212529);
}

:deep(.btn-secondary:hover:not(:disabled)) {
    background: #dde0e3;
}

:deep(.btn-danger) {
    background: #dc3545;
    color: white;
}

:deep(.btn-danger:hover:not(:disabled)) {
    background: #bb2d3b;
}

:deep(.btn-sm) {
    padding: 0.375rem 0.75rem;
    font-size: 0.8rem;
}

:deep(.message) {
    padding: 0.75rem 1rem;
    border-radius: 6px;
    font-size: 0.9rem;
    font-weight: 500;
    margin-bottom: 1rem;
}

:deep(.message.success) {
    background: #d1e7dd;
    color: #0f5132;
    border: 1px solid #badbcc;
}

:deep(.message.error) {
    background: #f8d7da;
    color: #842029;
    border: 1px solid #f5c2c7;
}

:deep(.loading) {
    color: var(--text-secondary, #6c757d);
    font-style: italic;
}

@page "/settings"
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-dashboard">
    <SettingsSidebar ActiveSection="@_activeSection"
                     OnSectionChanged="section => _activeSection = section" />

    <main class="settings-content">
        @switch (_activeSection)
        {
            case "Profile":
                <ProfileSection />
                break;
            case "Notifications":
                <NotificationsSection />
                break;
